WITH t_0_V AS (SELECT * FROM VALUES
  (1, "2024-01-01"),
  (2, "2024-02-28"),
  (3, "2024-02-29"),
  (4, "2023-03-01"),
  (5, "2000-12-31"),
  (6, "1999-07-15"),
  (7, "2026-10-06"),
  (8, "1970-01-01"),
  (9, "2100-02-28"),
  (10, "2004-08-09")
AS UNUSED_TABLE_NAME(id, d))
SELECT
  V.id AS id
FROM
  t_0_V AS V
WHERE
  ((MOD(((((((((((((((365) * (((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1970))))) + (((CAST((CASE WHEN ((((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1969))) < 0) <> ((4) < 0) THEN CEIL(CAST(((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1969)) AS DOUBLE) / NULLIF(4, 0)) ELSE FLOOR(CAST(((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1969)) AS DOUBLE) / NULLIF(4, 0)) END) AS BIGINT)) - (CAST((CASE WHEN ((((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1901))) < 0) <> ((100) < 0) THEN CEIL(CAST(((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1901)) AS DOUBLE) / NULLIF(100, 0)) ELSE FLOOR(CAST(((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1901)) AS DOUBLE) / NULLIF(100, 0)) END) AS BIGINT)))))) + (CAST((CASE WHEN ((((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1601))) < 0) <> ((400) < 0) THEN CEIL(CAST(((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1601)) AS DOUBLE) / NULLIF(400, 0)) ELSE FLOOR(CAST(((CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT)) - (1601)) AS DOUBLE) / NULLIF(400, 0)) END) AS BIGINT)))) + (CASE WHEN ((CAST(ROUND(SUBSTR(V.d, 6, 2)) AS BIGINT) > 2) AND ((((MOD(CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT), NULLIF(4, 0))) = 0) AND ((MOD(CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT), NULLIF(100, 0))) != 0)) OR ((MOD(CAST(ROUND(SUBSTR(V.d, 1, 4)) AS BIGINT), NULLIF(400, 0))) = 0))) THEN 1 ELSE 0 END))) + (ELEMENT_AT(ARRAY(0, 31, 59, 90, 120, 151, 181, 212, 243, 273, 304, 334), ((CAST(ROUND(SUBSTR(V.d, 6, 2)) AS BIGINT)) - (1)) + 1)))) + (((CAST(ROUND(SUBSTR(V.d, 9, 2)) AS BIGINT)) - (1))))) + (3)), NULLIF(7, 0))) >= 5) ORDER BY id NULLS LAST;